import hmac
import hashlib
import base64
import json
import time
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('JWT_SECRET', os.urandom(32))

ALLOWED_ALGORITHMS = ['HS256', 'HS384', 'HS512']
TOKEN_EXPIRY = 3600

def b64url_encode(data):
    if isinstance(data, str):
        data = data.encode('utf-8')
    return base64.urlsafe_b64encode(data).rstrip(b'=')

def b64url_decode(data):
    if isinstance(data, str):
        data = data.encode('utf-8')
    padding = 4 - len(data) % 4
    if padding != 4:
        data += b'=' * padding
    return base64.urlsafe_b64decode(data)

def get_hash_func(algorithm):
    mapping = {
        'HS256': hashlib.sha256,
        'HS384': hashlib.sha384,
        'HS512': hashlib.sha512,
    }
    return mapping.get(algorithm)

def sign_token(payload, secret, algorithm='HS256'):
    header = {'alg': algorithm, 'typ': 'JWT'}
    header_b64 = b64url_encode(json.dumps(header, separators=(',', ':')))
    payload_b64 = b64url_encode(json.dumps(payload, separators=(',', ':')))
    signing_input = header_b64 + b'.' + payload_b64
    hash_func = get_hash_func(algorithm)
    signature = hmac.new(secret if isinstance(secret, bytes) else secret.encode(),
                         signing_input, hash_func).digest()
    sig_b64 = b64url_encode(signature)
    return (signing_input + b'.' + sig_b64).decode('utf-8')

def verify_token(token, secret):
    """Verify JWT token with algorithm validation.

    Security: Only allows HMAC-based algorithms from ALLOWED_ALGORITHMS.
    Rejects tokens with 'none' algorithm or RSA/EC algorithms.
    """
    try:
        parts = token.split('.')
        if len(parts) != 3:
            return None, 'Invalid token structure'

        header_b64, payload_b64, sig_b64 = parts

        # Decode and validate header
        header = json.loads(b64url_decode(header_b64))

        if not isinstance(header, dict):
            return None, 'Invalid header format'

        algorithm = header.get('alg', '')

        # Security check: validate algorithm is in allowlist
        # This prevents algorithm confusion attacks
        if algorithm not in ALLOWED_ALGORITHMS:
            # Check if it's a case variation of 'none'
            if algorithm.lower() == 'none':
                return None, 'Algorithm none is not allowed'
            return None, f'Unsupported algorithm: {algorithm}'

        # Verify signature
        signing_input = (header_b64 + '.' + payload_b64).encode('utf-8')
        hash_func = get_hash_func(algorithm)

        expected_sig = hmac.new(
            secret if isinstance(secret, bytes) else secret.encode(),
            signing_input, hash_func
        ).digest()

        actual_sig = b64url_decode(sig_b64)

        if not hmac.compare_digest(expected_sig, actual_sig):
            return None, 'Invalid signature'

        # Decode payload
        payload = json.loads(b64url_decode(payload_b64))

        if not isinstance(payload, dict):
            return None, 'Invalid payload format'

        # Check expiration
        exp = payload.get('exp', 0)
        if time.time() > exp:
            return None, 'Token expired'

        return payload, None

    except Exception as e:
        return None, f'Token verification failed: {str(e)}'

def require_auth(f):
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'Missing authorization'}), 401

        token = auth_header[7:]
        secret = app.config['SECRET_KEY']
        payload, error = verify_token(token, secret)

        if error:
            return jsonify({'error': error}), 401

        g.user = payload
        return f(*args, **kwargs)
    decorated.__name__ = f.__name__
    return decorated

