@app.route('/api/login', methods=['POST'])
def login():
    body = request.get_json(force=True)
    username = body.get('username', '')
    password = body.get('password', '')

    # Simplified auth for demo
    if username == 'admin' and password == 'admin123':
        role = 'admin'
    elif username and password == 'user123':
        role = 'user'
    else:
        return jsonify({'error': 'Invalid credentials'}), 401

    payload = {
        'sub': username,
        'role': role,
        'iat': int(time.time()),
        'exp': int(time.time()) + TOKEN_EXPIRY
    }

    token = sign_token(payload, app.config['SECRET_KEY'])
    return jsonify({'token': token})

@app.route('/api/admin/data', methods=['GET'])
@require_auth
def get_admin_data():
    if g.user.get('role') != 'admin':
        return jsonify({'error': 'Admin access required'}), 403
    return jsonify(admin_data)

@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    return jsonify({'user': g.user.get('sub'), 'role': g.user.get('role')})

@app.route('/api/verify', methods=['POST'])
def verify_external_token():
    """Verify a token from an external service.

    External services may use different signing keys.
    The token's 'iss' claim determines which key to use.
    """
    body = request.get_json(force=True)
    token = body.get('token', '')

    # Parse header to determine issuer without full verification
    try:
        parts = token.split('.')
        if len(parts) != 3:
            return jsonify({'valid': False, 'error': 'Bad structure'}), 400

        header = json.loads(b64url_decode(parts[0]))
        payload_raw = json.loads(b64url_decode(parts[1]))

        issuer = payload_raw.get('iss', 'self')

        # Get the appropriate key for this issuer
        issuer_keys = {
            'self': app.config['SECRET_KEY'],
            'partner-api': os.environ.get('PARTNER_KEY', 'partner-default-key'),
            'internal': os.environ.get('INTERNAL_KEY', 'internal-default-key'),
        }

        key = issuer_keys.get(issuer)
        if key is None:
            return jsonify({'valid': False, 'error': 'Unknown issuer'}), 400

        # Full verification with appropriate key
        payload, error = verify_token(token, key)
        if error:
            return jsonify({'valid': False, 'error': error}), 400

        return jsonify({'valid': True, 'payload': payload})

    except Exception as e:
        return jsonify({'valid': False, 'error': str(e)}), 400

